// Turns the escalate_requests() result into at most two digest emails:
// level 1 (at risk) goes to the Automation team, level 2 (breached) to the
// team lead. Nothing is sent when no request moved up a level this run.
const r = $input.first().json.result;
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const when = (h) => (h < 0 ? `${Math.abs(h)} h overdue` : `in ${h} h`);

const table = (items) => `
<table cellpadding="6" cellspacing="0" border="1" style="border-collapse:collapse;font-size:13px">
  <tr style="background:#f3f4f6"><th align="left">Request</th><th align="left">Title</th><th align="left">Department</th>
  <th>Priority</th><th align="left">Assigned to</th><th align="left">Due (${esc(r.timezone)})</th><th align="left">When</th></tr>
  ${items.map((i) => `<tr><td>${esc(i.request_id)}</td><td>${esc(i.title)}</td><td>${esc(i.department)}</td>
  <td align="center">${esc(i.priority)}</td><td>${esc(i.assigned_to || 'Unassigned')}</td><td>${esc(i.due_local)}</td>
  <td>${esc(when(i.hours_to_due))}</td></tr>`).join('')}
</table>`;

const mail = (to, subject, intro, items) => ({
  json: {
    from: r.mail_from,
    to,
    subject,
    html: `<div style="font-family:Arial,sans-serif;font-size:14px"><p>${intro}</p>${table(items)}
           <p><a href="${esc(r.queue_url)}">Open the request queue</a></p></div>`,
  },
});

const out = [];
if (r.at_risk.length) {
  out.push(mail(r.team_email,
    `[Service Desk] SLA at risk: ${r.at_risk.length} request(s) due soon`,
    'These open requests are due within the next 24 hours. Please pick them up or update their status.',
    r.at_risk));
}
if (r.breached.length) {
  out.push(mail(r.lead_email,
    `[Service Desk] SLA breached: ${r.breached.length} request(s) escalated to you`,
    'These open requests are past their SLA due date and have been escalated to you.',
    r.breached));
}
return out;
